CREATE TABLE IF NOT EXISTS npc_spawn_territory_edges (
    territory_tag TEXT NOT NULL
  , pos_x INTEGER NOT NULL
  , pos_y INTEGER NOT NULL
  , min_z INTEGER NOT NULL
  , max_z INTEGER NOT NULL CHECK (max_z > min_z)
  , FOREIGN KEY (territory_tag) REFERENCES npc_spawn_territories (tag)
);

DELETE FROM npc_spawn_territory_edges;
